// TH18 v1.00a st01.ecl MainSub04 (s:1570-1618), Stage 1 mid-stage wave 5.
// 27 source creations: 9x Cir01a (40f steps, s:1576-1593) then 2 rounds of 9x
// Cir02a (20f steps, s:1598-1616). Each create is followed by its source wait,
// so the schedule spans 720 frames: 0..320 step40, then 360..700 step20.
// Cir01a: s:216-226 -> Cir01func 227-244 -> async Cir01_at 185-215.
// Cir02a: s:276-289 -> Cir02func 290-307 -> async Cir02_at 245-275.
// Upstream parent is the stage control enemy at FINAL (0,0); MainSub04 reads no
// I/F slots and each firing task initialises its own et0 (sh_reset).
const TIME_LIMIT: int = 1300;      // 120 opening buffer + 720 source + 460 tail estimate
const OPENING_BUFFER: int = 120;
const TH18_BALL2: int = 432;      // source etSprite type5 Ball2, native radius 4

// Cir01_at s:185-215. Rank selects the wake-up wait, shot count and layer speed;
// etSpeedD(1.0,1.3,3.0,4.0,...) is one layer, so only the start speed is used.
async sub cir01_at() {
    var rank: int = global(GVAR_RANK);
    var w: int = 0;
    if rank == 2 { w = rand(60); } else { w = 30 + rand(200); } // s:188-196
    var shots: int = 0;                                        // diffI(A,0,0,1,1)
    var speed: fx = 1fx;
    if rank == 1 { speed = 1.3fx; }
    if rank == 2 { shots = 1; speed = 3fx; }
    if rank == 3 { shots = 1; speed = 4fx; }
    wait(w);
    sh_reset(0);                     // s:198-206 etNew/etAim(0,0)/etSprite(5,4)
    sh_sprite(0, TH18_BALL2, 4);
    sh_count(0, 1, 1);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, speed, 0fx);
    sh_dist(0, -4fx*speed);          // s:205 EX type2 ANIM: position -= 4*initial velocity
    for k in 0..shots {              // s:208-212: etOn; wait(40)
        sh_fire(0);
        wait(40);
    }
}

// Cir02_at s:245-275, same emitter with diffI(A,1,2,2,3).
async sub cir02_at() {
    var rank: int = global(GVAR_RANK);
    var w: int = 0;
    if rank == 0 { w = 30 + rand(200); }
    if rank == 1 { w = 30 + rand(100); }
    if rank == 2 { w = rand(60); }
    if rank == 3 { w = 30 + rand(200); }
    var shots: int = 1;
    var speed: fx = 1fx;
    if rank == 1 { shots = 2; speed = 1.3fx; }
    if rank == 2 { shots = 2; speed = 3fx; }
    if rank == 3 { shots = 3; speed = 4fx; }
    wait(w);
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 4);
    sh_count(0, 1, 1);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, speed, 0fx);
    sh_dist(0, -4fx*speed);          // s:265 EX type2 ANIM: position -= 4*initial velocity
    for k in 0..shots {
        sh_fire(0);
        wait(40);
    }
}

// Cir01func s:227-244. Source centre start (-32 y) and moveVel(pi/2 + RANDF2*10deg,2).
// Hit/hurt boxes are the source setHurtbox(28,28)/setHitbox(16,16) native circles.
async sub cir01a() {
    set_invuln(65535);               // RL shell: enemy cannot be killed by held SHOT
    set_hurtbox(14fx);
    set_hitbox(8fx);
    var u: fx = (rand(65536)-32768) as fx / 32768;  // %RANDF2
    move_vel(0, 90deg + ((u*1820fx) as int as angle), 2fx, EASE_LINEAR);
    spawn cir01_at();
    loop { wait(1000); }             // s:240-241 wait(60), loop wait(1000)
}

// Cir02func s:290-307, speed 3.
async sub cir02a() {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    var u: fx = (rand(65536)-32768) as fx / 32768;
    move_vel(0, 90deg + ((u*1820fx) as int as angle), 3fx, EASE_LINEAR);
    spawn cir02_at();
    loop { wait(1000); }
}

// One source enmCreate: x = base + %RANDF2*32, evaluated per creation (s:1576-1592).
sub spawn_cir01(base: fx) {
    var u: fx = (rand(65536)-32768) as fx / 32768;
    _ = spawn_enemy(base + u*32fx, -32fx, 200, 0, 0, 0, cir01a);
}
sub spawn_cir02(base: fx) {
    var u: fx = (rand(65536)-32768) as fx / 32768;
    _ = spawn_enemy(base + u*32fx, -32fx, 140, 0, 0, 0, cir02a);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn_cir01(0fx); wait(40);
    spawn_cir01(64fx); wait(40);
    spawn_cir01(-120fx); wait(40);
    spawn_cir01(-32fx); wait(40);
    spawn_cir01(120fx); wait(40);
    spawn_cir01(0fx); wait(40);
    spawn_cir01(-96fx); wait(40);
    spawn_cir01(-32fx); wait(40);
    spawn_cir01(32fx); wait(40);     // trailing wait -> first Cir02a at 360
    for round in 0..2 {
        spawn_cir02(0fx); wait(20);
        spawn_cir02(64fx); wait(20);
        spawn_cir02(-120fx); wait(20);
        spawn_cir02(-32fx); wait(20);
        spawn_cir02(120fx); wait(20);
        spawn_cir02(0fx); wait(20);
        spawn_cir02(-96fx); wait(20);
        spawn_cir02(-32fx); wait(20);
        spawn_cir02(32fx); wait(20);
    }
    loop { wait(600); }
}

async sub encounter() {
    // Training-only phase owner at (0,0) with no body collision; source enemies
    // keep their own hit/hurt boxes.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
